package ultra.downloads;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import android.content.Context;import android.graphics.*;import android.graphics.drawable.BitmapDrawable;import android.os.Looper;import android.widget.ImageView;import java.io.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ArtTest {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();app.revanced.extension.shared.utils.Utils.testContext=c;Art.network=false;Art.memory.evictAll();synchronized(Art.failures){Art.failures.clear();}synchronized(Art.waiting){Art.waiting.clear();}}
 Library.Item item(String id){Library.Item i=new Library.Item();i.id=id;i.title=id;return i;}
 void fixture(String id,boolean letterbox)throws Exception{Bitmap b=Bitmap.createBitmap(480,360,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(b);cv.drawColor(letterbox?Color.BLACK:0xff2040c0);Paint p=new Paint();p.setColor(0xff2040c0);if(letterbox)cv.drawRect(0,45,480,315,p);File f=Art.file(c,id);f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 boolean waitFor(ImageView v){for(int n=0;n<100;n++){try{Thread.sleep(20);}catch(InterruptedException e){}Shadows.shadowOf(Looper.getMainLooper()).idle();if(v.getDrawable() instanceof BitmapDrawable)return true;}return false;}
 @Test public void concurrentRequestsShareOneJobAndBothViewsGetTheBitmap()throws Exception{fixture("abcdefghijk",false);Library.Item i=item("abcdefghijk");ImageView one=new ImageView(c),two=new ImageView(c);int before=Art.started.get();Art.load(c,i,one,56);Art.load(c,i,two,56);assertEquals("one job for one id",before+1,Art.started.get());assertTrue(waitFor(one));assertTrue(waitFor(two));ImageView three=new ImageView(c);Art.load(c,i,three,56);assertTrue("served from memory",three.getDrawable() instanceof BitmapDrawable);assertEquals(before+1,Art.started.get());}
 @Test public void recycledViewNeverShowsAnotherSongsArt()throws Exception{fixture("abcdefghijk",false);ImageView v=new ImageView(c);Art.load(c,item("abcdefghijk"),v,56);v.setTag("lmnopqrstuv");for(int n=0;n<20;n++){Thread.sleep(20);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertNotNull("Missing artwork uses the app icon",v.getDrawable());assertFalse(v.getDrawable() instanceof BitmapDrawable);}
 @Test public void missingArtworkWithoutNetworkQueuesNothing(){ImageView v=new ImageView(c);int before=Art.started.get();Art.load(c,item("zzzzzzzzzzz"),v,56);assertEquals(before,Art.started.get());assertNotNull("Missing artwork uses the app icon",v.getDrawable());assertFalse(v.getDrawable() instanceof BitmapDrawable);}
 @Test public void failuresBackOffAndStop(){String id="bbbbbbbbbbb";assertTrue(Art.retryAllowed(id,0));Art.failed(id,1000);assertFalse(Art.retryAllowed(id,1000+Art.RETRY_MS-1));assertTrue(Art.retryAllowed(id,1000+Art.RETRY_MS));Art.failed(id,50000);assertFalse(Art.retryAllowed(id,50000+Art.RETRY_MS));assertTrue(Art.retryAllowed(id,50000+2*Art.RETRY_MS));Art.failed(id,200000);assertFalse("bounded attempts",Art.retryAllowed(id,Long.MAX_VALUE/2));Art.succeeded(id);assertTrue(Art.retryAllowed(id,0));}
 @Test public void letterboxIsTrimmedButDarkArtworkIsKept(){Bitmap boxed=Bitmap.createBitmap(120,90,Bitmap.Config.ARGB_8888);new Canvas(boxed).drawColor(Color.BLACK);Paint p=new Paint();p.setColor(Color.WHITE);new Canvas(boxed).drawRect(0,11,120,79,p);Bitmap t=Art.trim(boxed);assertEquals(68,t.getHeight());
  Bitmap dark=Bitmap.createBitmap(120,90,Bitmap.Config.ARGB_8888);new Canvas(dark).drawColor(Color.WHITE);new Canvas(dark).drawRect(0,0,120,20,new Paint());assertSame("one-sided dark edge is artwork",dark,Art.trim(dark));}
 @Test public void persistedFileDecodesNearDisplaySize()throws Exception{fixture("ccccccccccc",true);Bitmap b=Art.decode(Art.file(c,"ccccccccccc"),56);assertNotNull(b);assertTrue(b.getWidth()<=240);assertTrue("bars trimmed",b.getHeight()<b.getWidth()*3/4);assertTrue(Color.blue(b.getPixel(b.getWidth()/2,1))>150);}
 @Test public void localOnlyAudioNeverQueuesOnlineArtworkLookup()throws Exception{Art.network=true;Library.Item i=item("placeholder");i.imported=true;i.uri="content://media/external/audio/media/654321";i.id=LocalAudio.localId(i.uri);assertFalse(Catalog.metadataAllowed(i));int before=Art.started.get();Art.load(c,i,new ImageView(c));assertEquals(before,Art.started.get());}
 @Test public void matchedImportedAndOnlineIdsRemainEligible()throws Exception{Library.Item i=item("abcdefghijk");assertTrue(Catalog.metadataAllowed(i));i.imported=true;i.uri="content://media/external/audio/media/654322";assertTrue(Catalog.metadataAllowed(i));i.id="playlist_example";assertFalse(Catalog.metadataAllowed(i));}
}
